package com.fse.core;
import org.springframework.context.annotation.*;
public class SpringCoreDemo { public static void main(String[] args) { try (var context = new AnnotationConfigApplicationContext(Config.class)) { System.out.println(context.getBean(GreetingService.class).greet("Java FSE")); } } @Configuration static class Config { @Bean GreetingRepository greetingRepository() { return name -> "Welcome, " + name; } @Bean GreetingService greetingService(GreetingRepository repository) { return new GreetingService(repository); } } interface GreetingRepository { String findGreeting(String name); } static class GreetingService { private GreetingRepository repository; GreetingService(GreetingRepository repository) { this.repository = repository; } void setRepository(GreetingRepository repository) { this.repository = repository; } String greet(String name) { return repository.findGreeting(name); } } }
